export function parseSemanticDecision(text:string) {
  try{return decisionSchema.safeParse(JSON.parse(text.replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/,"").trim()));}
  catch{return decisionSchema.safeParse(null);}
}
