const normalized=(s:string)=>s.normalize("NFKC").toLowerCase().replace(/[\s「」『』“”"']/g,"");
/** Titles identify a retrieval target, never its contents. Recognize the actual
 * longest catalog title in the current utterance before accepting model splits. */
export function mentionedCatalogWorks(works:CatalogWork[],query:string) {
  const q=normalized(query);
  const found=works.filter(w=>{
    const title=normalized(w.title??'');if(title.length<3)return false;
    if(/[ぁ-んァ-ヶ一-龯]/.test(title))return q.includes(title);
    const literal=(w.title??'').normalize('NFKC').toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\s+/g,'\\s+');
    return new RegExp(`(?<![\\p{L}\\p{N}])${literal}(?![\\p{L}\\p{N}])`,'u').test(query.normalize('NFKC').toLowerCase());
  }).sort((a,b)=>(b.title?.length??0)-(a.title?.length??0));
  return found.filter(w=>!found.some(other=>other!==w&&normalized(other.title??'').length>normalized(w.title??'').length&&normalized(other.title??'').includes(normalized(w.title??'')))).slice(0,4);
}
