/** Semantic labels are proposals. URLs, catalog IDs, product facts and pacing are server-owned. */
export function semanticActionGate(d:SemanticDecision,messages:Message[]) {
  const latest=messages.filter(m=>m.role==="user").at(-1)?.content??"";
  const pacing=analyzeValueSales(messages);
  const priorStop=[...messages].reverse().find(m=>m.role==="assistant"&&typeof m.salesStopped==="boolean")?.salesStopped===true;
  const revoked=d.salesStopRevoked&&d.revocationQuote.trim().length>2&&latest.includes(d.revocationQuote)&&hasCurrentCommerceInquiry(latest);
  const boundary=classifyCommercialBoundary(latest);
  // “見るだけ” / “今日は買わない” are browsing boundaries, not a persistent
  // commercial opt-out. Keep model-recognized opt-outs for other languages,
  // unless the current words are specifically a non-purchase browsing signal.
  const modelRequestedStop=d.explicitSalesStopActive||d.stance==="opt_out"||d.route==="stop";
  const stop=(priorStop&&!revoked)||boundary.explicitOptOut||(modelRequestedStop&&!boundary.browsingWithoutPurchase);
  const proactiveAllowed=!stop&&d.route!=="care"&&pacing.appeals<3&&!pacing.lastTurnWasAppeal&&Boolean(d.valueAngle)&&!pacing.usedAngles.includes(d.valueAngle!);
  const p=products.find(p=>p.id===d.productId);
  const purchaseAllowed=d.route==="purchase"&&d.explicitCurrentPurchase&&d.purchaseQuote.trim().length>1&&latest.includes(d.purchaseQuote)&&!stop&&!d.noLinks&&d.stance!=="paused"&&Boolean(p?.available);
  return {stop,pacing,proactiveAllowed,purchaseAllowed,product:p};
}
export function verifiedSelfSources(ids:string[]) {
  return [...new Set(ABI_PUBLIC_KNOWLEDGE.facts.filter(f=>ids.includes(f.id)).flatMap(f=>f.source.split(";").flatMap(source=>source.startsWith("official:/")?[source.slice("official:".length)]:source.startsWith("https://www.hakusyaku.xyz/")?[source.replace("https://www.hakusyaku.xyz","")]:[])))].slice(0,3);
}
const priceOnly=(price:number,lang:string)=>lang==="ja"?`表示価格は${price.toLocaleString("ja-JP")}円です。`:lang==="fr"?`Le prix affiché est de ${price.toLocaleString("fr-FR")} yens.`:lang==="de"?`Der angezeigte Preis beträgt ${price.toLocaleString("de-DE")} Yen.`:lang==="es"?`El precio indicado es de ${price.toLocaleString("es-ES")} yenes.`:lang==="ar"?`السعر المعروض هو ${price} ين ياباني.`:`The listed price is JPY ${price.toLocaleString("en-US")}.`;
export function resolveCatalogRoute(d:SemanticDecision) {
  if(d.route==='evidence'&&d.sourceDomain==='registered'&&d.catalogIntent==='exploration')return 'recommend' as const;
  if(d.route!=="catalog")return d.route;
  if(d.constraints.titles.length)return "work" as const;
  if(d.catalogIntent==='exploration')return 'recommend' as const;
  if(d.catalogIntent==='named_work')return 'work' as const;
  return d.route;
}
export function validateGroundedAnswer(g:z.infer<typeof groundedSchema>|null,rows:ReturnType<typeof evidenceRow>[],maxSelections=3,requirements:ReturnType<typeof currentWorkRequirements>=[]) {
  return Boolean(g)&&g!.selectedIds.length<=maxSelections&&new Set(g!.selectedIds).size===g!.selectedIds.length&&g!.selectedIds.every(id=>rows.some(r=>r.id===id&&satisfiesWorkRequirements(r,requirements)))&&validateClaimSelection(g!.selectedIds,g!.evidence,evidenceClaims(rows))&&(!g!.selectedIds.length||g!.supported&&!g!.unknownConditions.length)&&! /https?:\/\/|www\./i.test(g!.answer);
}

/** A failed required condition can still have a valid, discussable premise.
 * It must never create a recommendation card or a satisfied-match claim. */
export function partialDiscussionIds(g:z.infer<typeof groundedSchema>|null,rows:ReturnType<typeof evidenceRow>[],maxSelections=3) {
  if(!g||g.supported||!g.unknownConditions.length||!g.selectedIds.length||g.selectedIds.length>maxSelections||new Set(g.selectedIds).size!==g.selectedIds.length)return [];
  if(g.selectedIds.some(id=>!rows.some(r=>r.id===id))||!validateClaimSelection(g.selectedIds,g.evidence,evidenceClaims(rows))||/https?:\/\/|www\./i.test(g.answer))return [];
  return [...g.selectedIds];
}

export function evidenceRow(w:CatalogWork) {
  const e=catalogEvidence(w);
  const editorial=editorialKnowledge.items.find(x=>x.workId===String(w.id)&&x.title===w.title);
  const edition=w.title?.match(/\((?:English|German|French|Spanish|Japanese) Edition\)/i)?.[0]??"";
  return {id:String(w.id),title:w.title??"",type:w.type??"",basis:e.basis,source:e.source,
    description:e.description.slice(0,800),edition,ownerCuration:ABI_PUBLIC_KNOWLEDGE.curation.filter(c=>c.workId===String(w.id)||ownerWorkBindings.items.some(b=>b.sourceWorkId===c.workId&&b.canonicalWorkId===String(w.id)&&b.title===w.title&&getPublicLinksForCard(w).some(l=>l.url===b.evidenceHref))).map(c=>c.kind==="OWNER_SELECTED_REPRESENTATIVE"?"本人があえて挙げる代表作の一つ。客観ランキングや音質評価ではない。":"本人が現在気に入っている作品の一つ。内容や音質の証明ではない。").join(" "),vocals:vocalEvidenceFor(w).status,
    metadata:e.basis==="content_derived"||e.basis==="inferred_not_used"?[]:e.basis==="public_editorial"?editorial?.facets??[]:e.source.startsWith('registered_metadata:')?linkedCatalogMetadata(w)?.metadata??[]:[...w.tags??[],...w.moodTags??[]].filter(t=>! /inferred|title-only/.test(t)).slice(0,10)};
}
export function candidateWorks(works:CatalogWork[],d:SemanticDecision,messages:Message[],rejectedIds:string[]) {
  const c=d.constraints, priorLedger=[...messages].reverse().find(m=>m.conversationLedger)?.conversationLedger, seen=messages.filter(m=>m.role==="assistant").map(m=>normalized(m.content)).join("\n");
  const requested=c.titles.map(normalized);
  const literal=mentionedCatalogWorks(works,messages.filter(m=>m.role==='user').at(-1)?.content??'');
  const named=literal.length?literal:works.filter(w=>requested.some(t=>t===normalized(w.title??"")));
  const requirements=currentWorkRequirements(messages,c.type);
  if(d.route==="work"&&(requested.length||literal.length))return named.filter(w=>satisfiesWorkRequirements(evidenceRow(w),requirements)).slice(0,4);
  const tokens=c.query.toLowerCase().split(/[\s、,。;]+/).filter(t=>t.length>1);
  const conditions:CatalogConstraint[]=c.conditions.map(x=>({...x,label:x.id}));
  return works.filter(w=>!rejectedIds.includes(String(w.id))&&!w.catalogStatus?.identityConflict&&w.catalogStatus?.recommendationEligible!==false&&(!c.type||w.type===c.type)&&(!c.different||!seen.includes(normalized(w.title??"")))).map(w=>{
    const e=evidenceRow(w),text=[e.description,e.edition,...e.metadata].join(" ");
    return {w,e,text,score:(d.proactiveValue?(discoveryBridge(e,messages)?.score??0)*10:0)+tokens.reduce((n,t)=>n+(text.toLowerCase().includes(t)?1:0),0)+(e.basis==="content_derived"||e.basis==="public_editorial"?1:0)};
  }).filter(x=>satisfiesWorkRequirements(x.e,requirements)&&satisfiesCatalogConstraints(x.text,conditions)&&(x.w.type!=="music"||!c.noVocals||x.e.vocals==="confirmed_no_vocals"))
    .sort((a,b)=>b.score-a.score).slice(0,40).map(x=>x.w);
}
